import numpy as np
import os, sys
sys.path.append('storage/verity')
import scp_lp_core as core

def _fallback_grid():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0, 5)) and (iy in (0, 5)):
                continue
            centers.append([x, y])
    return np.array(centers, dtype=float)

def construct_packing() -> tuple:
    seeds = []
    C0 = core.seed_storage_best()
    if C0 is not None:
        seeds.append(("storage-best", C0))
        for amp, seed in [(0.001, 7301), (0.0005, 7303), (0.00025, 7305)]:
            Cj = core.seed_storage_best_jitter(amplitude=amp, seed=seed)
            if Cj is not None:
                seeds.append((f"storage-best-jitter-{amp}", Cj))
    else:
        seeds.append(("grid-36minus4", _fallback_grid()))

    best_sum = -1.0; best_C = None; best_r = None
    for name, C in seeds:
        C = np.clip(C, 0.0, 1.0)
        print(f"[seed] {name}")
        C_opt, r_opt, s = core.candidate_optimize(C, max_outer=120, min_tau=5e-4, verbose=False)
        print(f"[seed] {name} -> score {s:.9f}")
        if s > best_sum:
            best_sum, best_C, best_r = s, C_opt, r_opt

    # Finalize again with zero tolerance (idempotent)
    best_r = core.finalize_minimal(best_C, best_r, neg_tol=0.0)

    try:
        os.makedirs("storage/verity", exist_ok=True)
        np.save("storage/verity/best_centers.npy", best_C)
        np.save("storage/verity/best_radii.npy", best_r)
    except Exception:
        pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
